package com.mps.document.model;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="document_version") public class DocumentVersion {
 @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="document_id") private DocumentRecord document; @Column(name="version_number",nullable=false) private int versionNumber; @Column(name="original_filename",nullable=false,length=255) private String originalFilename; @Column(name="stored_filename",nullable=false,length=255) private String storedFilename; @Column(name="content_type",nullable=false,length=150) private String contentType; @Column(name="size_bytes",nullable=false) private long sizeBytes; @Column(nullable=false,length=64) private String sha256; @Column(name="storage_path",nullable=false,length=1000) private String storagePath; @Column(name="version_notes",length=500) private String versionNotes; @Column(name="uploaded_by",nullable=false) private UUID uploadedBy; @Column(name="uploaded_at",nullable=false) private Instant uploadedAt=Instant.now();
 protected DocumentVersion(){} public DocumentVersion(DocumentRecord d,int number,String original,String stored,String type,long size,String sha,String path,String notes,UUID by){document=d;versionNumber=number;originalFilename=original;storedFilename=stored;contentType=type;sizeBytes=size;sha256=sha;storagePath=path;versionNotes=notes==null||notes.isBlank()?null:notes.trim();uploadedBy=by;}
 public UUID getId(){return id;} public DocumentRecord getDocument(){return document;} public int getVersionNumber(){return versionNumber;} public String getOriginalFilename(){return originalFilename;} public String getStoredFilename(){return storedFilename;} public String getContentType(){return contentType;} public long getSizeBytes(){return sizeBytes;} public String getSha256(){return sha256;} public String getStoragePath(){return storagePath;} public String getVersionNotes(){return versionNotes;} public Instant getUploadedAt(){return uploadedAt;}
}
